from author import add, save, write
write('shared/passwords.mjs', '''
import {scrypt,randomBytes,timingSafeEqual} from 'node:crypto';import {promisify} from 'node:util';
const run=promisify(scrypt),options={N:131072,r:8,p:1,maxmem:256*1024*1024};
export async function hashPassword(password){if(typeof password!=='string'||password.length<8||password.length>256)throw Error('Password length must be 8..256');const salt=randomBytes(16).toString('hex');return 'v1:'+salt+':'+(await run(password,salt,64,options)).toString('hex');}
export async function verifyPassword(password,stored){if(typeof password!=='string'||password.length>256||!/^v1:[0-9a-f]{32}:[0-9a-f]{128}$/.test(stored))return false;const [,salt,hex]=stored.split(':');return timingSafeEqual(await run(password,salt,64,options),Buffer.from(hex,'hex'));}
''')
write('shared/task-api.mjs', '''
import Fastify from 'fastify';import {SignJWT,jwtVerify} from 'jose';import {randomUUID} from 'node:crypto';import {transaction} from './postgres.mjs';import {hashPassword,verifyPassword} from './passwords.mjs';
const issuer='https://course.example',audience='tasks-api';
export async function buildTaskApi({pool,key,afterFirstInsert=async()=>{},logger=false}){
 if(!(key instanceof Uint8Array)||key.length<32)throw Error('Supply a 32-byte signing key');
 const app=Fastify({bodyLimit:4096,logger:logger?{redact:{paths:['req.headers.authorization','password'],remove:true}}:false});const state={started:false,stopping:false};app.decorate('courseState',state);
 app.addHook('onReady',async()=>{await pool.query('SELECT 1');state.started=true;});app.addHook('preClose',async()=>{state.stopping=true;});
 app.get('/live',async()=>({alive:true}));app.get('/ready',async(q,r)=>{if(!state.started||state.stopping)return r.code(503).send({ready:false});try{await pool.query('SELECT 1');return{ready:true};}catch{return r.code(503).send({ready:false});}});
 const credentials={type:'object',required:['email','password'],properties:{email:{type:'string',minLength:3,maxLength:200},password:{type:'string',minLength:8,maxLength:256}},additionalProperties:false};
 app.post('/register',{schema:{body:credentials}},async(q,r)=>{const id=randomUUID(),password=await hashPassword(q.body.password);try{await pool.query('INSERT INTO users(id,email,password) VALUES($1,$2,$3)',[id,q.body.email,password]);return r.code(201).send({id});}catch(e){if(e.code==='23505')return r.code(409).send({error:'Already registered'});throw e;}});
 app.post('/login',{schema:{body:credentials}},async(q,r)=>{const row=(await pool.query('SELECT * FROM users WHERE email=$1',[q.body.email])).rows[0];if(!row||!await verifyPassword(q.body.password,row.password))return r.code(401).send({error:'Invalid credentials'});const token=await new SignJWT({sub:row.id}).setProtectedHeader({alg:'HS256'}).setIssuer(issuer).setAudience(audience).setIssuedAt().setExpirationTime('15m').sign(key);return{token};});
 async function auth(q,r){try{const raw=q.headers.authorization;if(!raw?.startsWith('Bearer '))throw Error('Missing bearer');q.user=(await jwtVerify(raw.slice(7),key,{algorithms:['HS256'],issuer,audience})).payload;}catch{return r.code(401).send({error:'Unauthorized'});}}
 const titleBody={type:'object',required:['title'],properties:{title:{type:'string',minLength:1,maxLength:200}},additionalProperties:false};
 app.get('/tasks',{preHandler:auth},async q=>(await pool.query('SELECT id,title,version FROM tasks WHERE owner_id=$1 ORDER BY id',[q.user.sub])).rows);
 app.post('/tasks',{preHandler:auth,schema:{body:titleBody}},async(q,r)=>r.code(201).send((await pool.query('INSERT INTO tasks(title,owner_id) VALUES($1,$2) RETURNING id,title,version',[q.body.title,q.user.sub])).rows[0]));
 app.get('/tasks/:id',{preHandler:auth},async(q,r)=>{if(!/^\\d+$/.test(q.params.id))return r.code(400).send({error:'Invalid id'});const row=(await pool.query('SELECT id,title,version FROM tasks WHERE id=$1 AND owner_id=$2',[q.params.id,q.user.sub])).rows[0];return row??r.code(404).send({error:'Not found'});});
 app.patch('/tasks/:id',{preHandler:auth,schema:{body:{...titleBody,required:['title','version'],properties:{...titleBody.properties,version:{type:'integer',minimum:0}}}}},async(q,r)=>{if(!/^\\d+$/.test(q.params.id))return r.code(400).send({error:'Invalid id'});const changed=await pool.query('UPDATE tasks SET title=$1,version=version+1 WHERE id=$2 AND owner_id=$3 AND version=$4 RETURNING id,title,version',[q.body.title,q.params.id,q.user.sub,q.body.version]);if(changed.rowCount)return changed.rows[0];const own=await pool.query('SELECT id FROM tasks WHERE id=$1 AND owner_id=$2',[q.params.id,q.user.sub]);return r.code(own.rowCount?409:404).send({error:own.rowCount?'Version conflict':'Not found'});});
 app.delete('/tasks/:id',{preHandler:auth},async(q,r)=>{if(!/^\\d+$/.test(q.params.id))return r.code(400).send({error:'Invalid id'});const changed=await pool.query('DELETE FROM tasks WHERE id=$1 AND owner_id=$2',[q.params.id,q.user.sub]);return changed.rowCount?r.code(204).send():r.code(404).send({error:'Not found'});});
 app.post('/tasks/batch',{preHandler:auth,schema:{body:{type:'object',required:['titles'],properties:{titles:{type:'array',minItems:2,maxItems:2,items:{type:'string',minLength:1,maxLength:200}}}}}},async(q,r)=>{const rows=await transaction(pool,async client=>{const out=[];for(const [index,title] of q.body.titles.entries()){out.push((await client.query('INSERT INTO tasks(title,owner_id) VALUES($1,$2) RETURNING id,title',[title,q.user.sub])).rows[0]);if(index===0)await afterFirstInsert();}return out;});return r.code(201).send(rows);});
 app.setErrorHandler((error,q,r)=>{if(error.validation)return r.code(400).send({error:'Invalid input'});q.log.error({err:error},'request failed');return r.code(500).send({error:'Internal error'});});return app;
}
export async function registerAndLogin(app,email='a@course.invalid'){const password='public-fixture-password';const registered=await app.inject({method:'POST',url:'/register',payload:{email,password}});if(registered.statusCode!==201)throw Error('Registration failed');const response=await app.inject({method:'POST',url:'/login',payload:{email,password}});if(response.statusCode!==200)throw Error('Login failed');return{user:registered.json(),headers:{authorization:'Bearer '+response.json().token}};}
''')
add(96,'''import {assert,fs,temp,join,spawnNode} from '../../shared/lab.mjs';await using lab=await temp();const path=join(lab.path,'secret.txt');await fs.writeFile(path,'public-fixture-only');for(const valid of [true,false]){const env={...process.env,APP_SECRET:'',APP_SECRET_FILE:''};delete env.APP_SECRET;if(valid)env.APP_SECRET_FILE=path;const r=await spawnNode(['config.mjs'],{env});console.log({valid,code:r.code,stdout:r.stdout,stderr:r.stderr});assert.equal(r.code,valid?0:1);assert.ok(!r.stdout.includes('public-fixture-only'));}''','A mounted-file fixture configures the app; missing configuration fails generically and never prints the secret.',files={'config.mjs':"import {readFile} from 'node:fs/promises';try{const value=process.env.APP_SECRET??(process.env.APP_SECRET_FILE?await readFile(process.env.APP_SECRET_FILE,'utf8'):'');if(!value.trim())throw Error('Missing secret');console.log({secretConfigured:true});}catch{console.error('Configuration unavailable');process.exitCode=1;}"})
add(97,'''import {hashPassword,verifyPassword} from '../../shared/passwords.mjs';import assert from 'node:assert/strict';const password='public-fixture-password';const first=await hashPassword(password),second=await hashPassword(password);assert.notEqual(first,second);assert.equal(await verifyPassword(password,first),true);assert.equal(await verifyPassword('wrong-password',first),false);assert.equal(await verifyPassword(password,'malformed'),false);console.log('random salts differ; correct=true, wrong=false, malformed=false');''','Versioned, salted scrypt records verify correctly without logging passwords or hashes.','The fixed cost is N=131072,r=8,p=1 with a bounded maxmem setting. Each active derivation uses substantial memory; bound authentication concurrency and measure your deployment.')
add(98,'''import Fastify from 'fastify';import secureSession from '@fastify/secure-session';import csrf from '@fastify/csrf-protection';import {randomBytes} from 'node:crypto';import assert from 'node:assert/strict';const app=Fastify();await app.register(secureSession,{key:randomBytes(32),expiry:3600,cookie:{path:'/',httpOnly:true,secure:true,sameSite:'lax'}});await app.register(csrf,{sessionPlugin:'@fastify/secure-session'});app.get('/session',async(q,r)=>{q.session.set('user','user-a');return{token:await r.generateCsrf()};});app.post('/transfer',{onRequest:[async(q,r)=>{if(!q.session.get('user'))return r.code(401).send({error:'Unauthorized'});},app.csrfProtection]},async()=>({accepted:true}));try{const session=await app.inject('/session');const cookie=session.cookies.map(c=>c.name+'='+c.value).join('; '),token=session.json().token;assert.ok(session.headers['set-cookie'].includes('Secure'));const missing=await app.inject({method:'POST',url:'/transfer',headers:{cookie}});const valid=await app.inject({method:'POST',url:'/transfer',headers:{cookie,'csrf-token':token}});assert.equal(missing.statusCode,403);assert.equal(valid.statusCode,200);console.log('secure encrypted session cookie; missing CSRF=403, valid CSRF=200');}finally{await app.close();}''','Real session and CSRF plugins reject the missing token and accept the matching one. Tokens and keys are not printed.','This is in-process HTTP injection for behavior verification. A browser deployment requires HTTPS for the Secure cookie. Expiry and per-user revocation policy need dedicated deployment tests.',deps=['fastify','@fastify/secure-session','@fastify/csrf-protection'])
add(99,'''import {SignJWT,jwtVerify} from 'jose';import {randomBytes} from 'node:crypto';import assert from 'node:assert/strict';const key=randomBytes(32);async function token(audience='tasks-api',expiry='15m'){return new SignJWT({sub:'user-1'}).setProtectedHeader({alg:'HS256'}).setIssuer('https://course.example').setAudience(audience).setIssuedAt().setExpirationTime(expiry).sign(key);}const options={algorithms:['HS256'],issuer:'https://course.example',audience:'tasks-api'};assert.equal((await jwtVerify(await token(),key,options)).payload.sub,'user-1');await assert.rejects(jwtVerify(await token('wrong'),key,options));await assert.rejects(jwtVerify(await token('tasks-api',0),key,options));await assert.rejects(jwtVerify(await token(),randomBytes(32),options));console.log('valid token accepted; audience, expiry and signature failures rejected');''','Signature and claim validation accepts only the expected issuer/audience/algorithm and a live expiry. No tokens are logged.',deps=['jose'])
add(100,'''import {pgLab} from '../../shared/postgres.mjs';import {buildTaskApi,registerAndLogin} from '../../shared/task-api.mjs';import {randomBytes} from 'node:crypto';import assert from 'node:assert/strict';await using db=await pgLab();const app=await buildTaskApi({pool:db.pool,key:randomBytes(32)});try{const a=await registerAndLogin(app,'a@course.invalid'),b=await registerAndLogin(app,'b@course.invalid');const created=await app.inject({method:'POST',url:'/tasks',headers:a.headers,payload:{title:'private'}});const id=created.json().id;for(const method of ['GET','DELETE']){const response=await app.inject({method,url:'/tasks/'+id,headers:b.headers});assert.equal(response.statusCode,404);}assert.equal((await app.inject({url:'/tasks/'+id,headers:a.headers})).statusCode,200);assert.equal((await app.inject('/tasks')).statusCode,401);console.log('owner=200, another user=404, unauthenticated=401');}finally{await app.close();}''','Real signed identities and PostgreSQL owner predicates prevent cross-user access.',mode='postgres',deps=['fastify','pg','jose'])
add(101,'''import {createHmac,randomBytes,timingSafeEqual} from 'node:crypto';import {pgLab,transaction} from '../../shared/postgres.mjs';import assert from 'node:assert/strict';await using db=await pgLab();const key=randomBytes(32),timestamp=String(Math.floor(Date.now()/1000)),raw=Buffer.from(JSON.stringify({id:'event-1',amount:10}));const sign=body=>createHmac('sha256',key).update(timestamp+'.').update(body).digest('hex');function verify(body,time,signature){if(!/^\\d+$/.test(time)||!/^[0-9a-f]{64}$/i.test(signature)||Math.abs(Date.now()/1000-Number(time))>300)return false;return timingSafeEqual(createHmac('sha256',key).update(time+'.').update(body).digest(),Buffer.from(signature,'hex'));}const signature=sign(raw);assert.equal(verify(Buffer.from('{}'),timestamp,signature),false);assert.equal(verify(raw,'1',signature),false);async function apply(){assert.ok(verify(raw,timestamp,signature));const event=JSON.parse(raw);return transaction(db.pool,async client=>{const inserted=await client.query('INSERT INTO processed_events VALUES($1) ON CONFLICT DO NOTHING RETURNING id',[event.id]);if(inserted.rowCount)await client.query('UPDATE accounts SET balance=balance+$1 WHERE id=1',[event.amount]);return inserted.rowCount;});}assert.equal(await apply(),1);assert.equal(await apply(),0);assert.equal((await db.pool.query('SELECT balance FROM accounts WHERE id=1')).rows[0].balance,110);console.log('tamper/stale rejected; repeated signed event has one durable effect');''','Raw-byte signature verification precedes parsing; a database transaction combines durable deduplication and the business update.',mode='postgres',deps=['pg'])
add(102,'''import assert from 'node:assert/strict';const key=await crypto.subtle.generateKey({name:'AES-GCM',length:256},false,['encrypt','decrypt']),nonce=crypto.getRandomValues(new Uint8Array(12)),aad=new TextEncoder().encode('record:v1'),plain=new TextEncoder().encode('hello');const options={name:'AES-GCM',iv:nonce,additionalData:aad};const encrypted=await crypto.subtle.encrypt(options,key,plain);console.log(new TextDecoder().decode(await crypto.subtle.decrypt(options,key,encrypted)));const changed=new Uint8Array(encrypted.slice(0));changed[0]^=1;await assert.rejects(crypto.subtle.decrypt(options,key,changed));console.log('tampered ciphertext rejected');''','Authenticated encryption round-trips hello and rejects a modified ciphertext. Nonces must be unique per key.')
add(103,'''import {createServer} from 'node:http';import {assert,listen,close} from '../../shared/lab.mjs';const server=createServer((q,s)=>{if(q.url==='/redirect'){s.writeHead(302,{location:'http://127.0.0.1:9/private'});s.end();}else s.end(q.url==='/large'?'x'.repeat(2048):'allowed');});const base=await listen(server),destinations=new Map([['docs',new URL(base)],['redirect',new URL('/redirect',base)],['large',new URL('/large',base)]]);async function download(name){const url=destinations.get(name);if(!url)throw Error('Unknown destination');const response=await fetch(url,{redirect:'error',signal:AbortSignal.timeout(1000)});let bytes=0;try{for await(const chunk of response.body){bytes+=chunk.length;if(bytes>1024)throw Error('Body too large');}return bytes;}finally{if(!response.body.locked)await response.body.cancel().catch(()=>{});}}try{console.log('allowlisted bytes',await download('docs'));await assert.rejects(download('http://internal.invalid'),/Unknown/);await assert.rejects(download('redirect'));await assert.rejects(download('large'),/large/);console.log('unknown destination, redirect and body budget rejected');}finally{await close(server);}''','A server-owned destination map, redirect rejection and body cap are tested against a real loopback fixture.')
add(104,'''import Fastify from 'fastify';import rateLimit from '@fastify/rate-limit';import assert from 'node:assert/strict';const app=Fastify({bodyLimit:1024,trustProxy:false});await app.register(rateLimit,{max:20,timeWindow:'1 minute'});app.get('/work',async()=>({ok:true}));app.post('/payload',async()=>({ok:true}));try{for(let i=0;i<20;i++)assert.equal((await app.inject('/work')).statusCode,200);assert.equal((await app.inject('/work')).statusCode,429);const oversized=await app.inject({method:'POST',url:'/payload',remoteAddress:'127.0.0.2',payload:{text:'x'.repeat(2048)}});assert.equal(oversized.statusCode,413);console.log('rate budget=429; independent oversized request=413');}finally{await app.close();}''','The actual rate-limit plugin enforces 20 requests per window and the body cap rejects a separate oversized request.',deps=['fastify','@fastify/rate-limit'])
add(105,'''import {assert,fs,spawnNode} from '../../shared/lab.mjs';await fs.mkdir('./lab/output',{recursive:true});const flags=['--permission','--allow-fs-read=./lab','--allow-fs-write=./lab/output'];let r=await spawnNode([...flags,'lab/main.mjs']);console.log(r.stdout);assert.equal(r.code,0,r.stderr);r=await spawnNode([...flags,'lab/denied.mjs']);assert.notEqual(r.code,0);assert.ok(r.stderr.includes('ERR_ACCESS_DENIED'));console.log('outside read denied');''','Granted read/write work; a read outside the grant fails. The permission model is not a malicious-code sandbox.',files={'lab/input.txt':'hello','outside.txt':'public outside fixture','lab/main.mjs':"import {readFile,writeFile} from 'node:fs/promises';const text=await readFile(new URL('./input.txt',import.meta.url),'utf8');await writeFile(new URL('./output/result.txt',import.meta.url),text.toUpperCase());console.log('done');",'lab/denied.mjs':"import {readFile} from 'node:fs/promises';await readFile(new URL('../outside.txt',import.meta.url));"})
